toggle.example:
kcds.core.Events.on('playerCommand', (player, command) => {
  if (command !== 'gate') {
    return;
  }
  const gate = kcds.world.Gate.all('trosecko')[0];
  if (!gate.toggle()) {
    kcds.core.Chat.sendToPlayer(player, 'The gate is still moving.');
  }
});

toggle.exampleCs:
Events.On("playerCommand", (Player player, string command) =>
{
    if (command != "gate")
    {
        return;
    }
    var gate = Gate.All("trosecko")[0];
    if (!gate.Toggle())
    {
        Chat.SendToPlayer(player, "The gate is still moving.");
    }
});

